#!/usr/bin/env node
// "Paylaş > Descall": copies the share sheet strings (src/i18n/locales/shareSheet.<locale>.js,
// the single source) to the native share surfaces:
//   ios/App/DescallShare/ShareStrings.swift          every key, ICU plural kept (ShareText.swift formats it)
//   android/app/src/main/res/values(-xx)/share_strings.xml   the notification / worker subset
// Run after editing the catalogs: node scripts/gen-share-native-strings.mjs
// --check exits 1 when a generated file is out of date (scripts/gen-share-native-strings.selftest.mjs).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const LOCALES = [
  ["tr", "TR", "values-tr"],
  ["en", "EN", "values"],
  ["de", "DE", "values-de"],
  ["es", "ES", "values-es"],
  ["fr", "FR", "values-fr"],
  ["pt-BR", "PT_BR", "values-pt-rBR"],
  ["ru", "RU", "values-ru"],
];
// Android keys (worker notifications and the share activity). Placeholders become positional
// arguments in alphabetical order of their names: notif.draft → %1$s = chats, %2$s = items.
const ANDROID_KEYS = [
  "title", "items", "chats", "notif.channel", "notif.sending", "notif.sent", "notif.failedItems", "notif.waiting",
  "notif.stop", "notif.undo", "notif.openChat", "notif.retry", "notif.details", "notif.sendDraft", "notif.draft",
  "hide", "offline.queuedTitle", "undone.hero", "undone.failed", "failed.hero", "partial.title", "scheduled.title",
  "reason.failed", "reason.offline", "reason.upload_failed", "reason.signed_out", "reason.cancelled", "reason.too_large",
  "reason.type", "reason.no_permission", "reason.slowmode", "reason.rate_limited", "reason.timeout",
];

function flatten(obj, prefix = "", out = {}) {
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === "object") flatten(v, key, out);
    else out[key] = String(v);
  }
  return out;
}

async function load() {
  const out = {};
  for (const [id, suffix] of LOCALES) {
    const mod = await import(pathToFileURL(join(root, "src", "i18n", "locales", `shareSheet.${id}.js`)).href);
    out[id] = flatten(mod[`SHARE_SHEET_${suffix}`]);
  }
  return out;
}

function swiftLiteral(s) {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n")}"`;
}

function swift(cat) {
  const lines = [
    "// Generated by frontend/scripts/gen-share-native-strings.mjs from src/i18n/locales/shareSheet.<locale>.js.",
    "// Do not edit: change the web catalog and run the script. ICU plurals are formatted by ShareText.",
    "",
    "// One function per locale filling its table with plain assignments: a single nested",
    "// dictionary literal of every locale made the optimized (Release) build run for 40+ minutes.",
    "enum ShareStrings {",
    "    static let table: [String: [String: String]] = [",
  ];
  const fn = (id) => `locale_${id.replace(/[^A-Za-z0-9]/g, "_")}`;
  for (const [id] of LOCALES) lines.push(`        ${swiftLiteral(id)}: ${fn(id)}(),`);
  lines.push("    ]");
  for (const [id] of LOCALES) {
    const entries = Object.entries(cat[id]).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    lines.push("", `    private static func ${fn(id)}() -> [String: String] {`, `        var t = [String: String](minimumCapacity: ${entries.length})`);
    for (const [k, v] of entries) lines.push(`        t[${swiftLiteral(k)}] = ${swiftLiteral(v)}`);
    lines.push("        return t", "    }");
  }
  lines.push("}", "");
  return lines.join("\n");
}

function placeholders(s) {
  const names = new Set();
  const plural = /^\{(\w+), plural,/.exec(s);
  if (plural) names.add(plural[1]);
  for (const m of s.replace(/^\{\w+, plural,/, "").matchAll(/\{(\w+)\}/g)) names.add(m[1]);
  return [...names].sort();
}

function androidEscape(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/"/g, '\\"').replace(/@/g, "\\@").replace(/\?/g, "\\?");
}

function androidArgs(s, order, typeOf) {
  return s.replace(/\{(\w+)\}/g, (_, n) => `%${order.indexOf(n) + 1}$${typeOf(n)}`).replace(/#/g, `%${order.indexOf("count") + 1}$d`);
}

function android(cat, id) {
  const lines = ['<?xml version="1.0" encoding="utf-8"?>', "<!-- Generated by frontend/scripts/gen-share-native-strings.mjs from src/i18n/locales/shareSheet.*.js. Do not edit. -->", "<resources>"];
  for (const key of ANDROID_KEYS) {
    const v = cat[id][key];
    if (v == null) throw new Error(`${id}: missing ${key}`);
    const name = `share_${key.replace(/[.-]/g, "_")}`;
    const order = placeholders(v);
    const typeOf = (n) => (["count", "seconds", "done"].includes(n) ? "d" : "s");
    const m = /^\{(\w+), plural,(.*)\}$/s.exec(v);
    if (m) {
      lines.push(`    <plurals name="${name}">`);
      for (const pm of m[2].matchAll(/(zero|one|two|few|many|other)\s*\{((?:[^{}]|\{\w+\})*)\}/g)) {
        lines.push(`        <item quantity="${pm[1]}">${androidEscape(androidArgs(pm[2], order, typeOf))}</item>`);
      }
      lines.push("    </plurals>");
    } else {
      lines.push(`    <string name="${name}"${order.length ? "" : ' formatted="false"'}>${androidEscape(androidArgs(v, order, typeOf))}</string>`);
    }
  }
  lines.push("</resources>", "");
  return lines.join("\n");
}

export async function generate() {
  const cat = await load();
  const files = [[join(root, "ios", "App", "DescallShare", "ShareStrings.swift"), swift(cat)]];
  for (const [id, , dir] of LOCALES) files.push([join(root, "android", "app", "src", "main", "res", dir, "share_strings.xml"), android(cat, id)]);
  return { cat, files };
}

if (import.meta.url === pathToFileURL(process.argv[1] || "").href) {
  const check = process.argv.includes("--check");
  const { files } = await generate();
  let stale = 0;
  for (const [path, body] of files) {
    let cur = null;
    try { cur = readFileSync(path, "utf8"); } catch { cur = null; }
    if (cur === body) continue;
    if (check) {
      stale += 1;
      console.error(`out of date: ${path}`);
    } else {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, body);
      console.log(`wrote ${path}`);
    }
  }
  if (check && stale) process.exit(1);
}
